package edu.klh.soa.workflow;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="consumed_event") public class ConsumedEvent {@Id public String eventId;@Column(nullable=false)public String aggregateId;@Column(nullable=false)public String correlationId;@Column(nullable=false)public String status;@Column(nullable=false)public Instant consumedAt;protected ConsumedEvent(){}public ConsumedEvent(String id,String agg,String corr){eventId=id;aggregateId=agg;correlationId=corr;status="QUARANTINED";consumedAt=Instant.now();}}